from ta_moler.cmd.egate.generictabcontent import GenericTabContent
from moler.exceptions import ParsingDone
import re


class SeqStats(GenericTabContent):
    """Seqstats epcsim command."""

    def __init__(self, connection, seq_id=None, at=None, output_format=None, prompt=None, newline_chars=None, runner=None):
        """
        Get Seqstats statistics.

        :param connection: moler connection to device, terminal when command is executed
        :param seq_id: command sequence identifier
        :param at: requested device (For UEC: uec[:n] displays info on UEC n); if omitted the configured sequences will be displayed
        :param output_format: display format; default = long
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(SeqStats, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.seq_id = seq_id
        self.at = at
        self.output_format = output_format

        self.current_ret["DICT"] = {}
        self._uec_id_log = None
        self._seq_id_log = None
        self._prefix = ''
        self._headers_for_two_columns = None
        self._headers_for_five_columns = None

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        cmd = "seq_stats"
        if self.seq_id:
            cmd = f"{cmd} id={self.seq_id}"
        if self.output_format:
            cmd = f"{cmd} format={self.output_format}"
        if self.at:
            cmd = f"{cmd} at=uec:{self.at}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_uec_and_seq(line)
            except ParsingDone:
                pass
        return super(SeqStats, self).on_new_line(line, is_full_line)

    # UE Command Sequence 101 Statistics on UEC 1
    _re_uec_and_seq = re.compile(r'.*Sequence\s(?P<SEQ_ID>.*)\sStatistics.*UEC\s(?P<UEC_ID>\d+)')

    def _parse_uec_and_seq(self, line):
        if self._regex_helper.search_compiled(SeqStats._re_uec_and_seq, line):
            self._seq_id_log = self._regex_helper.group("SEQ_ID")
            self._uec_id_log = self._regex_helper.group("UEC_ID")
            self.current_ret["DICT"][self._seq_id_log] = {}
            self.current_ret["DICT"][self._seq_id_log][self._uec_id_log] = {}
            raise ParsingDone

    def _parse_headers(self, line):
        row_divided_by_columns = re.split(r'\s{2,}', line)
        whitespaces_postfix = row_divided_by_columns[-1] == ''
        whitespaces_prefix = row_divided_by_columns[0] == ''
        if whitespaces_postfix:
            row_divided_by_columns = row_divided_by_columns[:-1]
        if whitespaces_prefix:
            row_divided_by_columns = row_divided_by_columns[1:]

        if len(row_divided_by_columns) >= 1 and row_divided_by_columns[0] == 'Parameter':
            if len(row_divided_by_columns) == 2:
                self._headers_for_two_columns = row_divided_by_columns[1:]
            elif len(row_divided_by_columns) == 5:
                self._headers_for_five_columns = row_divided_by_columns[1:]
            raise ParsingDone

    def _parse_data_row(self, line):
        row_divided_by_columns = re.split(r"\s{2,}", line)
        whitespaces_postfix = row_divided_by_columns[-1] == ''
        whitespaces_prefix = row_divided_by_columns[0] == ''
        if whitespaces_postfix:
            row_divided_by_columns = row_divided_by_columns[:-1]
        if whitespaces_prefix:
            row_divided_by_columns = row_divided_by_columns[1:]

        if len(row_divided_by_columns) == 1 and row_divided_by_columns[0][-1] == ':':
            self._prefix = f"{row_divided_by_columns[0][:-1]}-"
            raise ParsingDone
        if len(row_divided_by_columns) == 2:
            self._fill_dict(self._headers_for_two_columns, row_divided_by_columns)
        elif len(row_divided_by_columns) == 5:
            self._fill_dict(self._headers_for_five_columns, row_divided_by_columns)

    def _fill_dict(self, headers_for_x_columns, row_divided_by_columns):
        field_with_prefix = f"{self._prefix}{row_divided_by_columns[0]}"
        self.current_ret["DICT"][self._seq_id_log][self._uec_id_log][field_with_prefix] = {}
        for header, result in zip(headers_for_x_columns, row_divided_by_columns[1:]):

            # 238
            pattern_int = re.match(r"^\d+$", result)
            # 2108344 (0D:0H:35M:8S.344MS)
            pattern_str_int = re.match(r"^(\d+)\s\(.*\)$", result)
            # 4.20
            pattern_float = re.match(r"^\d+.\d+$", result)
            # 2148.09 (0D:0H:35M:48S.90MS)
            pattern_str_float = re.match(r"^(\d+\.\d+)\s\(.*\)$", result)

            if pattern_int:
                result = int(result)
            elif pattern_str_int:
                result = {"number": int(pattern_str_int.groups()[0]),
                          "initial": result}
            elif pattern_float:
                result = float(result)
            elif pattern_str_float:
                result = {"number": float(pattern_str_float.groups()[0]),
                          "initial": result}

            self.current_ret["DICT"][self._seq_id_log][self._uec_id_log][field_with_prefix][header] = result
        raise ParsingDone


